// Six CPU-heavy jobs, and a progress ticker that is supposed to prove
// the app is still alive while they run. Watch what actually happens.

function fib(n) {
  return n < 2 ? n : fib(n - 1) + fib(n - 2); // deliberately the slow way
}

const INPUTS = [33, 35, 34, 36, 33, 35];

const started = Date.now();
const ticks = [];
const ticker = setInterval(() => {
  ticks.push(Date.now() - started);
  process.stdout.write('.');
}, 100);

// Proof that the ticker works when nothing is in its way:
await new Promise((resolve) => setTimeout(resolve, 350));
console.log(`\nticker before the work: ${ticks.length} ticks in 350ms`);

// ---- the blocking part ---------------------------------------------
const workStarted = Date.now();
const ticksBefore = ticks.length;
const results = INPUTS.map(fib);   // <-- the event loop is now a hostage
const workMs = Date.now() - workStarted;

// Let the event loop breathe, so any queued ticks can finally fire.
await new Promise((resolve) => setImmediate(resolve));
clearInterval(ticker);

console.log(`results: ${results.join(', ')}`);
console.log(`CPU work took ${workMs}ms`);
console.log(`ticks expected during the work: ~${Math.floor(workMs / 100)}`);
console.log(`ticks that actually arrived:     ${ticks.length - ticksBefore}`);

// The ticker was not slow. It was FROZEN. `setInterval` doesn't
// promise "every 100ms"; it promises "queued every 100ms, run when
// the call stack is empty" — and `INPUTS.map(fib)` never empties it.
//
// Everything else in the process is frozen too: incoming HTTP
// requests, timers, promise callbacks, Ctrl-C handling. In a server
// this is not "slow", it is DOWN.
//
// And the machine? Eight cores, one of them busy. `async`/`await`
// cannot help: they interleave WAITING, and this code isn't waiting
// on anything — it's computing. To use another core you need another
// thread (project 84's refactor) or another process.
console.log(`cores available: ${(await import('node:os')).availableParallelism()}, cores used: 1`);

# 🏋️ Practice: Worker Pool

Do these after reading LEARN.md and the README. Solutions are at the bottom — try each exercise before peeking.

Work in `refactored/pool.js` (and its worker files); add your checks to `refactored/pool.test.js` and run `node --test 84-worker-pool/refactored/pool.test.js`. Starting threads costs real milliseconds, so share pool runs between assertions and keep the fib inputs tiny.

## Exercises

### ⭐ 1. unwrapPartial — the other half of unwrap (warm-up)

`unwrap` throws on the first failure. Often you want the opposite: everything that worked, plus a report of what didn't. Write `unwrapPartial(results)` returning `{ values, failures, okCount, failCount }`, where each failure is `{ index, error }`. No threads needed — this is plain array work over Results.

What it practices: Results are just data, so "what do I do about failures?" becomes a *caller's* decision instead of the pool's. Two callers can want two different things from the same batch.

Hint: one `forEach` with the index, pushing into two arrays.

Check (in node): `[{ok:true,value:2},{ok:false,error:'boom'},{ok:true,value:6}]` gives `values: [2, 6]`, `failures: [{ index: 1, error: 'boom' }]`, and `unwrapPartial([])` gives empty arrays with zero counts.

### ⭐⭐ 2. onProgress — a progress bar that tells the truth (core)

Add an `onProgress` option called after each item completes with `{ done, total, index, ok }`. Use it in `cli.js` to print `[####------] 4/10` on one line (`process.stdout.write('\r...')`).

What it practices: the pool already knows everything a progress bar needs; exposing it as a callback beats returning a giant object nobody reads. Note *where* the call belongs — in `finishItem`, the one place an item can complete.

Hint: `done` must count completions, not dispatches, or your bar will hit 100% while work is still running.

Check (in node): six items through a pool of two produce exactly six calls, `done` counts `1,2,3,4,5,6` with no repeats, every call carries `total: 6`, and the six `index` values are 0–5 in some order.

### ⭐⭐ 3. A per-item timeout (core)

Add a `timeoutMs` option: if a worker doesn't answer within that time, kill it, record `{ ok: false, error: 'timed out after Nms' }` for that item, and start a **replacement** worker so the pool keeps its width. Two traps wait for you: (a) a thread takes hundreds of milliseconds to boot, and that time must not count against the first item's clock — so have the worker post `{ ready: true }` when it loads, and arm the timer only then; (b) a wedged worker cannot be interrupted, only terminated.

What it practices: timeouts are how you stop trusting a component you don't control. It's also a lesson in what "hung" means — you can't ask a stuck thread to stop, you can only kill it.

Hint: add `if (item?.hangs) return;` to `echo-worker.js` so a test can create a worker that never answers. Ignore any message without an `index` — that's the ready signal, not a result.

Check (in node): with six items where the **first two hang**, a pool of two, and `timeoutMs: 400`, both hanging items come back timed out and the other four still complete — which can only happen if the pool replaced both dead workers.

### ⭐⭐⭐ 4. Chunking — stop paying the postage (challenge)

Every item currently costs one round trip. When items are cheap, the messaging dominates. Write `chunk(items, chunkSize)` and `runPoolChunked(items, workerFile, size, chunkSize)`: send *arrays* of inputs, have a `chunk-fib-worker.js` return an array of Results, then flatten back to one result per original item, still in order. A dead chunk must fail only its own items.

What it practices: batching is the standard fix for per-message overhead — the same idea as bulk database inserts. It also forces you to keep two levels of ordering straight.

Hint: `flatMap` is exactly the right tool for the flattening, and when a whole chunk fails you must expand that one error back into `chunk.length` failed items so the output length still matches the input.

Check (in node): `chunk([1,2,3,4,5], 2)` is `[[1,2],[3,4],[5]]`; `runPoolChunked([10, 20, 5, 'x', 12], CHUNK_FIB, 2, 2)` gives `ok` flags `[true,true,true,false,true]` with fibs `55, 6765, 5, 144` and the bad item's own error message.

### ⭐⭐⭐ 5. A pool you can keep (challenge)

The CLI showed that starting threads costs real time — and `runPool` throws its workers away after every batch. Write `createPool(workerFile, size)` returning `{ size, run(items), close() }` that starts its workers **once** and reuses them across batches. `run` must reject if the pool is closed or already busy, and must remove its message listeners when the batch ends.

What it practices: object lifetime. A pool that outlives a batch is faster and more dangerous — it can leak listeners, and it keeps the process alive until `close()`.

Hint: `worker.on('message', listener)` in `run`, `worker.off('message', listener)` when the batch finishes. Without the `off`, batch two's results also reach batch one's handler and the counts go haywire.

Check (in node): two batches of six through a `createPool(ECHO, 2)` give the right doubled values, and the `threadId` set is **identical** across both batches — proof the same two threads did both. `run([])` returns `[]`, and calling `run` after `close()` rejects with "pool is closed".

## Solutions

### 1. unwrapPartial

```js
export function unwrapPartial(results) {
  const values = [];
  const failures = [];
  results.forEach((result, index) => {
    if (result.ok) values.push(result.value);
    else failures.push({ index, error: result.error });
  });
  return { values, failures, okCount: values.length, failCount: failures.length };
}
```

WHY: keeping the `index` on each failure is what makes this useful — "item 37 failed" lets you retry exactly that input, while a bare list of error strings only lets you shrug. This is the whole argument for Result values over exceptions in a batch: an exception unwinds the stack and destroys the context of the ninety-nine items that were fine, whereas a value sits quietly in a slot until someone decides what it means. Verified by running: two values, two indexed failures, and zeroes for an empty batch.

### 2. onProgress

```js
// in runPool's finishItem — the one place an item can complete:
onProgress?.({ done: completed, total: items.length, index, ok: result.ok });

// in cli.js:
const bar = ({ done, total }) => {
  const filled = Math.round((done / total) * 20);
  process.stdout.write(`\r[${'#'.repeat(filled)}${'-'.repeat(20 - filled)}] ${done}/${total}`);
};
await runPool(INPUTS, FIB_WORKER, defaultPoolSize(), { onProgress: bar });
```

WHY: putting the call in `finishItem` rather than in the message handler means it fires for *every* way an item can end — a normal result, a caught throw, a dead worker, a timeout — so the bar can't stall at 9/10 because one item failed in an unusual way. That's the payoff of having funnelled all four endings through one function. `?.` keeps the option optional with no `if`. And notice the progress bar is only possible because the main thread is free: in `original.js` it would have printed nothing at all until the work was over. Verified by running: exactly six calls, `done` 1→6 with no repeats, all six indices present.

### 3. A per-item timeout

```js
// echo-worker.js gains one line at the top of the handler...
if (item?.hangs) return; // never answers
// ...and one at the very end of the file:
parentPort.postMessage({ ready: true });

// in pool.js's spawn():
let ready = timeoutMs === undefined; // no clock, no need to wait

const armTimer = () => {
  if (timeoutMs === undefined || current === -1 || !ready) return;
  const index = current;
  timer = setTimeout(() => {
    current = -1;
    workers.delete(worker);
    worker.terminate();                       // a wedged thread can only be killed
    if (!finished) finishItem(index, { ok: false, error: `timed out after ${timeoutMs}ms` });
    if (!finished && nextIndex < items.length) spawn(); // keep the pool wide
  }, timeoutMs);
};

worker.on('message', (message) => {
  if (finished) return;
  if (message.index === undefined) { ready = true; armTimer(); return; } // the worker booted
  clearTimer();
  ...
});
```

WHY: the `ready` handshake is the part you'd never guess and would spend an evening debugging. Arm the timer at dispatch and every *first* item fails on a cold pool, because booting a thread here can take longer than a reasonable timeout — you'd have built a pool that reliably kills its own workers. Measuring from "the thread is up" makes the timeout mean what it says: how long this *item* may take. The second subtlety is `spawn()` on expiry: without it, each timeout permanently narrows the pool, and enough timeouts leave you with zero workers and a batch that never finishes. Also note `worker.terminate()` rather than any polite request — a thread spinning in a loop never checks its messages, which is precisely why it's stuck. Verified by running: two hanging items out of six, a pool of two, `timeoutMs: 400` — both hangs reported, all four remaining items completed by the replacement workers.

### 4. Chunking

```js
export function chunk(items, chunkSize) {
  if (!Number.isInteger(chunkSize) || chunkSize < 1) {
    throw new RangeError(`chunkSize must be a positive integer, got ${chunkSize}`);
  }
  const chunks = [];
  for (let i = 0; i < items.length; i += chunkSize) chunks.push(items.slice(i, i + chunkSize));
  return chunks;
}

export async function runPoolChunked(items, workerFile, size, chunkSize, options) {
  const chunks = chunk(items, chunkSize);
  const chunkResults = await runPool(chunks, workerFile, size, options);
  return chunkResults.flatMap((result, i) =>
    result.ok ? result.value : chunks[i].map(() => ({ ok: false, error: result.error })));
}
```

```js
// chunk-fib-worker.js — one message in, an array of Results out
parentPort.on('message', ({ index, item: inputs }) => {
  const value = inputs.map((n) => {
    try { ... return { ok: true, value: { n, fib: fib(n) } }; }
    catch (error) { return { ok: false, error: error.message }; }
  });
  parentPort.postMessage({ index, ok: true, value });
});
```

WHY: the pool didn't change at all — chunking is a *caller-side* decision, because `runPool` never cared what an "item" is. That's the reward for making it generic over `items` and a worker file rather than hard-coding fib. The delicate line is the failure branch: when a whole chunk dies (a crashed worker, a timeout) you must expand that single error into one failure per input, or the returned array is shorter than the input and every index afterwards is silently wrong — a much nastier bug than the crash that caused it. Chunk size is a real trade-off: bigger chunks amortise the message cost but coarsen the failure granularity and can leave one worker holding the last fat chunk while the others idle. Verified by running: correct order across chunk boundaries, and the bad input failing alone inside its chunk.

### 5. A pool you can keep

```js
export function createPool(workerFile, size = defaultPoolSize()) {
  const workers = Array.from({ length: size }, () => new Worker(workerFile));
  let closed = false;
  let busy = false;

  return {
    get size() { return workers.length; },

    run(items) {
      if (closed) return Promise.reject(new Error('pool is closed'));
      if (busy) return Promise.reject(new Error('pool is already running a batch'));
      busy = true;
      return new Promise((resolve) => {
        const results = new Array(items.length);
        if (items.length === 0) { busy = false; resolve(results); return; }
        let nextIndex = 0;
        let completed = 0;
        const listeners = new Map();
        const cleanup = () => {
          for (const [worker, listener] of listeners) worker.off('message', listener);
          busy = false;
        };
        for (const worker of workers.slice(0, Math.min(size, items.length))) {
          const dispatch = () => {
            if (nextIndex >= items.length) return;
            const index = nextIndex++;
            worker.postMessage({ index, item: items[index] });
          };
          const listener = (message) => {
            results[message.index] = message.ok
              ? { ok: true, value: message.value }
              : { ok: false, error: message.error };
            completed++;
            if (completed === items.length) { cleanup(); resolve(results); return; }
            dispatch();
          };
          listeners.set(worker, listener);
          worker.on('message', listener);
          dispatch();
        }
      });
    },

    close() {
      closed = true;
      return Promise.all(workers.map((worker) => worker.terminate()));
    },
  };
}
```

WHY: `worker.off(...)` in `cleanup` is the line that matters. Listeners accumulate silently — batch three's worker would still be feeding batch one's `completed` counter — and this class of leak is why long-lived event emitters are a classic source of "it gets slower the longer it runs". The `busy` flag is an honest admission of a limitation: this simple version can't interleave two batches, so it says so loudly instead of corrupting both. `close()` is not optional politeness either: a live worker keeps the whole process alive, so a forgotten pool is a program that never exits. Note what's deliberately missing compared to `runPool` — crash and timeout handling — which is the exercise's real lesson: a warm pool needs a *worker replacement* policy, because a dead worker is now dead for every future batch too. Verified by running: identical `threadId` sets across two batches, `run([])` → `[]`, and `run` after `close()` rejecting.

import os from 'node:os';
import { defaultPoolSize, runPool, unwrap } from './pool.js';

// The same six jobs as original.js, twice: once on the main thread,
// once through the pool — with the same progress ticker watching.

const INPUTS = [33, 35, 34, 36, 33, 35];
const FIB_WORKER = new URL('./fib-worker.js', import.meta.url);

function fib(n) {
  return n < 2 ? n : fib(n - 1) + fib(n - 2);
}

function startTicker() {
  const ticks = [];
  const started = Date.now();
  const id = setInterval(() => {
    ticks.push(Date.now() - started);
    process.stdout.write('.');
  }, 100);
  return {
    ticks,
    stop() {
      clearInterval(id);
      return Date.now() - started;
    },
  };
}

console.log(`${os.availableParallelism()} cores available, pool size ${defaultPoolSize()}\n`);

// ---- 1. the original's way: everything on the main thread ----------
process.stdout.write('main thread ');
const blocking = startTicker();
const blockingResults = INPUTS.map((n) => fib(n));
await new Promise((resolve) => setImmediate(resolve)); // let queued ticks fire
const blockingMs = blocking.stop();
console.log(`\n  ${blockingMs}ms, ticker fired ${blocking.ticks.length} times ` +
  `(expected ~${Math.floor(blockingMs / 100)})`);

// ---- 2. the pool: the main thread only hands out work --------------
process.stdout.write('worker pool ');
const pooled = startTicker();
const results = await runPool(INPUTS, FIB_WORKER, defaultPoolSize());
const pooledMs = pooled.stop();
console.log(`\n  ${pooledMs}ms, ticker fired ${pooled.ticks.length} times ` +
  `(expected ~${Math.floor(pooledMs / 100)})`);

// ---- 3. what actually happened ------------------------------------
const values = unwrap(results);
console.log(`\nsame answers: ${JSON.stringify(values.map((v) => v.fib)) === JSON.stringify(blockingResults)}`);

// The workers report when they started and stopped, so we can separate
// "computing" from "starting up" — and starting a thread is NOT free.
const computeMs = Math.max(...values.map((v) => v.endedAt)) - Math.min(...values.map((v) => v.startedAt));
const cpuMs = values.reduce((sum, v) => sum + (v.endedAt - v.startedAt), 0);

console.log(`\n  main thread : ${blockingMs}ms`);
console.log(`  worker pool : ${pooledMs}ms  = ${pooledMs - computeMs}ms starting ` +
  `${defaultPoolSize()} threads + ${computeMs}ms computing`);
console.log(`  speedup on the computing part: ${(blockingMs / computeMs).toFixed(2)}x`);
console.log(`  CPU time spent: ${cpuMs}ms in ${computeMs}ms of clock time ` +
  `(${(cpuMs / computeMs).toFixed(2)} cores' worth)`);
console.log(`  (that last number is the honest one: it says how many cores this`);
console.log(`   machine actually gave us. On a busy laptop it will be near 1.)`);

console.log('\nper item:');
for (const value of values) {
  console.log(`  fib(${value.n}) = ${String(value.fib).padStart(8)}  ` +
    `thread ${value.threadId}  ${String(value.endedAt - value.startedAt).padStart(5)}ms`);
}

// Two lessons, and the second one is the one people skip:
//
// 1. The ticker didn't get faster — it got a CHANCE TO RUN. In the
//    first run the main thread was computing; in the second it was
//    idle, waiting for messages, which is what an event loop is for.
//
// 2. Threads cost real time to start (look at the number above). On
//    six quick jobs the pool can easily be SLOWER end-to-end; it wins
//    on long batches, or when what you care about is the process
//    staying responsive. Measure before you parallelise — "it uses all
//    my cores" is not the same claim as "it finished sooner".

import { parentPort, threadId } from 'node:worker_threads';

// A worker used only by pool.test.js. It can, on request: burn CPU for
// a while, double a number, throw, or die outright — so the tests can
// check what the pool does in each case.

/** Real CPU work, not a sleep: a sleeping thread proves nothing. */
function burn(ms) {
  const end = Date.now() + ms;
  while (Date.now() < end) { /* spin */ }
}

parentPort.on('message', ({ index, item }) => {
  const startedAt = Date.now();
  try {
    if (item?.crash) process.exit(3); // kills THIS thread, not the process
    if (item?.throws) throw new Error(`boom on item ${item.id}`);
    burn(item?.busyMs ?? 0);
    parentPort.postMessage({
      index,
      ok: true,
      value: { doubled: (item?.n ?? 0) * 2, threadId, startedAt, endedAt: Date.now() },
    });
  } catch (error) {
    parentPort.postMessage({ index, ok: false, error: error.message });
  }
});

import { parentPort, threadId } from 'node:worker_threads';

// A worker is a whole separate JavaScript world: its own event loop,
// its own memory, its own globals. It shares NOTHING with the main
// thread except the messages you post. That isolation is why threads
// here can't corrupt each other's variables — there are no shared
// variables to corrupt.

function fib(n) {
  return n < 2 ? n : fib(n - 1) + fib(n - 2); // deliberately the slow way
}

parentPort.on('message', ({ index, item }) => {
  const startedAt = Date.now();
  try {
    if (!Number.isInteger(item) || item < 0) {
      throw new RangeError(`fib needs a non-negative integer, got ${JSON.stringify(item)}`);
    }
    parentPort.postMessage({
      index, // ALWAYS echo the index back: it is how the pool reorders
      ok: true,
      value: { n: item, fib: fib(item), threadId, startedAt, endedAt: Date.now() },
    });
  } catch (error) {
    // A bad item is a value, not an explosion: report it and stay alive
    // for the next one.
    parentPort.postMessage({ index, ok: false, error: error.message });
  }
});

import { Worker } from 'node:worker_threads';
import os from 'node:os';

/**
 * A worker pool: run CPU-heavy work on several threads at once, with a
 * fixed number of threads, and get the answers back IN INPUT ORDER.
 *
 * Why threads and not async? `await` interleaves WAITING (a download, a
 * disk read). CPU work isn't waiting — it's using the one thread the
 * event loop runs on — so no amount of async can make two computations
 * overlap. Another core needs another thread. (Project 42 is the async
 * version of this same pool; the shape is identical, the reason is not.)
 *
 * Why a POOL and not one thread per item? Threads cost memory and
 * startup time, and more threads than cores just means the OS shuffles
 * them around. `size` workers pull from a shared queue until it's empty.
 *
 * Errors are values, not explosions: every result is `{ ok: true, value }`
 * or `{ ok: false, error }` (project 30's Result style), so one bad item
 * can never lose the other ninety-nine.
 */

/** Leave a core for the main thread, and don't get greedy. */
export function defaultPoolSize() {
  return Math.max(1, Math.min(4, os.availableParallelism() - 1));
}

export function runPool(items, workerFile, size = defaultPoolSize(), options = {}) {
  const { onActive } = options;
  if (!Array.isArray(items)) throw new TypeError('items must be an array');
  if (!Number.isInteger(size) || size < 1) {
    throw new RangeError(`size must be a positive integer, got ${size}`);
  }

  return new Promise((resolve, reject) => {
    const results = new Array(items.length);
    if (items.length === 0) {
      resolve(results);
      return;
    }

    let nextIndex = 0;  // the next item nobody has claimed
    let completed = 0;
    let active = 0;     // items currently being chewed on
    let finished = false;
    const workers = new Set();

    const settle = (finish, argument) => {
      if (finished) return;
      finished = true;
      for (const worker of workers) worker.terminate(); // threads don't stop themselves
      finish(argument);
    };

    const finishItem = (index, result) => {
      results[index] = result; // the item's ORIGINAL slot: order preserved
      completed++;
      active--;
      onActive?.(active);
      if (completed === items.length) settle(resolve, results);
    };

    for (let i = 0; i < Math.min(size, items.length); i++) {
      const worker = new Worker(workerFile);
      workers.add(worker);
      let current = -1; // which item this worker is holding, for crash cleanup

      const dispatch = () => {
        current = -1;
        if (nextIndex >= items.length) return; // queue empty: idle until terminated
        current = nextIndex++;
        active++;
        onActive?.(active);
        worker.postMessage({ index: current, item: items[current] });
      };

      worker.on('message', (message) => {
        if (finished) return;
        current = -1;
        finishItem(
          message.index,
          message.ok ? { ok: true, value: message.value } : { ok: false, error: message.error },
        );
        if (!finished) dispatch(); // this worker immediately takes the next item
      });

      // A worker can also die outright — a syntax error, an OOM, a call
      // to process.exit. That must cost us ONE item, not the batch.
      const die = (reason) => {
        if (finished) return;
        workers.delete(worker);
        worker.terminate();
        if (current !== -1) {
          const index = current;
          current = -1;
          finishItem(index, { ok: false, error: reason });
        }
        if (!finished && workers.size === 0 && completed < items.length) {
          settle(reject, new Error(
            `the pool lost every worker with ${items.length - completed} items unfinished`,
          ));
        }
      };

      worker.on('error', (error) => die(error.message));
      worker.on('exit', (code) => { if (code !== 0) die(`worker exited with code ${code}`); });

      dispatch();
    }
  });
}

/** Convenience: the values, throwing on the first failure (Promise.all semantics). */
export function unwrap(results) {
  return results.map((result, index) => {
    if (!result.ok) throw new Error(`item ${index} failed: ${result.error}`);
    return result.value;
  });
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { defaultPoolSize, runPool, unwrap } from './pool.js';

// Worker files must be addressed absolutely — a worker starts in its
// own world and doesn't inherit this file's location.
const FIB = new URL('./fib-worker.js', import.meta.url);
const ECHO = new URL('./echo-worker.js', import.meta.url);

// Starting a thread costs real milliseconds, so these tests share as
// few pool runs as possible and keep the fib inputs tiny. (Speed is a
// design constraint on tests too: a slow suite stops being run.)

/**
 * How many items were genuinely being computed AT THE SAME MOMENT?
 *
 * The windows are half-open — [start, end) — and ties are resolved
 * ends-first. That matters: Date.now() ticks about every 15ms on
 * Windows, so one worker's item can *end* on the same millisecond its
 * next item *begins*, and counting both would invent an overlap that
 * never happened.
 */
function peakOverlap(values) {
  const edges = values.flatMap((v) => [[v.startedAt, 1], [v.endedAt, -1]]);
  edges.sort((a, b) => a[0] - b[0] || a[1] - b[1]); // -1 before +1
  let active = 0;
  let peak = 0;
  for (const [, delta] of edges) {
    active += delta;
    peak = Math.max(peak, active);
  }
  return peak;
}

test('results keep INPUT order, and a bad item is a value not a crash', async () => {
  // Item 0 is the slowest, so it finishes last — and must still be first.
  const results = await runPool([26, 'twelve', 10, 20, -1], FIB, 2);

  assert.deepEqual(results.map((r) => r.ok), [true, false, true, true, false]);
  assert.deepEqual([results[0], results[2], results[3]].map((r) => r.value.fib), [121393, 55, 6765]);
  assert.match(results[1].error, /non-negative integer, got "twelve"/);
  assert.match(results[4].error, /non-negative integer, got -1/);
  assert.throws(() => unwrap(results), /item 1 failed/);
});

test('every item runs exactly once, and the pool size is respected', async (t) => {
  // Each worker reports the wall-clock window it was busy, so the
  // overlap below is measured INSIDE the threads, not inferred.
  const items = Array.from({ length: 10 }, (_, i) => ({ n: i, busyMs: 30 }));
  const seenActive = [];
  const values = unwrap(await runPool(items, ECHO, 2, { onActive: (n) => seenActive.push(n) }));

  assert.deepEqual(values.map((v) => v.doubled), items.map((i) => i.n * 2));
  assert.equal(new Set(values.map((v) => v.threadId)).size, 2, 'both workers took part');
  assert.equal(Math.max(...seenActive), 2, 'two items were in flight at once');
  assert.ok(peakOverlap(values) <= 2, `2 workers, but ${peakOverlap(values)} items overlapped`);

  // Whether those two in-flight items also overlap on the CLOCK depends
  // on the machine: if the second thread is slow to boot, the first can
  // drain the queue alone. Concurrency is ours to guarantee; parallelism
  // is the OS's to grant — so this one is reported, not asserted.
  t.diagnostic(`peak wall-clock overlap: ${peakOverlap(values)} of 2`);
});

test('failures cost one item each — a throw AND a hard crash', async () => {
  const items = [{ n: 1 }, { throws: true, id: 'bad' }, { crash: true }, { n: 4 }, { n: 5 }, { n: 6 }];
  const results = await runPool(items, ECHO, 2);

  assert.deepEqual(results.map((r) => r.ok), [true, false, false, true, true, true]);
  assert.match(results[1].error, /boom on item bad/);   // the worker caught it
  assert.match(results[2].error, /exited with code 3/); // the worker DIED
  for (const index of [0, 3, 4, 5]) {
    assert.equal(results[index].value.doubled, items[index].n * 2, `item ${index} still ran`);
  }
});

test('a size larger than the batch just uses fewer workers', async () => {
  const results = await runPool([{ n: 7 }], ECHO, 8);
  assert.equal(results.length, 1);
  assert.equal(results[0].value.doubled, 14);
});

test('an empty batch starts no threads at all', async () => {
  assert.deepEqual(await runPool([], FIB, 4), []);
});

test('silly pool sizes are rejected before any thread is created', () => {
  assert.throws(() => runPool([1], FIB, 0), RangeError);
  assert.throws(() => runPool([1], FIB, 2.5), RangeError);
  assert.throws(() => runPool('nope', FIB, 2), TypeError);
});

test('defaultPoolSize leaves the main thread a core and caps at 4', () => {
  const size = defaultPoolSize();
  assert.ok(Number.isInteger(size));
  assert.ok(size >= 1 && size <= 4, `got ${size}`);
});
